"""
MarketMind AI – Predictive Analysis Agent
"""
from typing import Dict, Any
from backend.data.sample_data import INDIAN_EV_MARKET
from backend.utils.granite_client import call_granite


DISCLAIMER = (
    "⚠️ AI-GENERATED PREDICTIONS: These forecasts are generated by MarketMind AI "
    "using trend analysis and IBM Granite AI. They are probabilistic estimates and "
    "should NOT be used as the sole basis for financial or investment decisions."
)


class PredictionAgent:
    SYSTEM_PROMPT = (
        "You are a predictive analytics expert. "
        "Generate clear, explainable forecasts with confidence levels. "
        "Always distinguish actual data from AI-generated predictions. "
        "Explain methodology and key assumptions."
    )

    def run(self, query: str, market_id: str, context: Dict[str, Any] = None) -> Dict[str, Any]:
        if market_id == "indian_ev" or "india" in query.lower() or "ev" in query.lower():
            forecast = INDIAN_EV_MARKET["forecast"]
            prompt = f"Generate predictive insights and forecast explanation for: {query}"
            ai_response = call_granite(
                prompt=prompt,
                system_prompt=self.SYSTEM_PROMPT,
                demo_response=(
                    "Forecast methodology: CAGR-based projection (49.5%) with policy adjustment factor. "
                    "Base case projects market reaching $113.99B by 2030 (from $4.89B in 2024). "
                    "Key assumptions: FAME III policy continuity, battery cost falling to $60/kWh by 2027, "
                    "charging stations scaling to 4.5L+ by 2030. "
                    "Risk-adjusted scenarios range from $31B (bear) to $72B (bull) by 2030. "
                    "Prediction confidence: Medium — dependent on policy stability and infrastructure roll-out."
                ),
            )
            return {
                **forecast,
                "disclaimer": DISCLAIMER,
                "ai_explanation": ai_response["text"],
                "ai_model": ai_response["model"],
                "opportunities": INDIAN_EV_MARKET["opportunities"],
                "agent": "PredictionAgent",
            }

        prompt = (
            f"Generate market forecasts and predictive insights for: {query}. "
            "Include: market size projection (5 years), key growth drivers, risks, "
            "and opportunities. Clearly mark all predictions as AI-generated estimates."
        )
        ai_response = call_granite(prompt=prompt, system_prompt=self.SYSTEM_PROMPT)
        return {
            "projections": [],
            "disclaimer": DISCLAIMER,
            "ai_explanation": ai_response["text"],
            "ai_model": ai_response["model"],
            "agent": "PredictionAgent",
        }
